// Function to compute the maximum height of an AVL tree
int maxHeight(Node* node) {
    if (node == NULL) return 0;
    return 1 + max(maxHeight(node->left), maxHeight(node->right));
}

// Function to return the last level of an AVL tree in a queue
queue<int> getBottomLevel(Node* root) {
    queue<int> ans, auxLevels, currLevels;
    ans.push(root->data);
    Node* oldRoot = root;
    while (1) {
        if (oldRoot->left || oldRoot->right) {
            currLevels.push(oldRoot->data);
            if (oldRoot->left) {
                auxLevels.push(oldRoot->left->data);
            }
            if (oldRoot->right) {
                auxLevels.push(oldRoot->right->data);
            }
        }
        int levelSize = currLevels.size();
        if (!levelSize) {
            break;
        }
        Node* newRoot = new Node(auxLevels.front()); // Use the queue front to form a new root
        currLevels.pop();

        // Traverse left and right subtrees
        for (int i = 0; i < levelSize; i++) {
            int value = currLevels.front();
            currLevels.pop();

            Node *left, *right;
            if (value <= newRoot->data) {
                left = generateNode(newRoot->left, value);
            } else {
                right = generateNode(newRoot->right, value);
            }
            if (left != NULL) {
                ans.push(left->data);
            }
            if (right != NULL) {
                ans.push(right->data);
            }
        }

        oldRoot = newRoot;
    }
    return ans;
}

int findSummationLastLevelQueue(int A) {
    Node *root = NULL;

    // Building the AVL tree
    for (int i = 1; i <= A; i++) {
        root = generateNode(root, i);
    }

    queue<int> lastLevelNodes = getBottomLevel(root);

    int ans = 0;
    while (!lastLevelNodes.empty()) {
        ans += lastLevelNodes.front();
        lastLevelNodes.pop();
    }
    return ans;
}

